<script setup lang="ts">
import {onMounted,ref} from 'vue';import {request} from '../../api/client';import {all,message} from '../sites/data';import type {Site} from '../sites/contracts';
type RuntimeStatus={mode:string;live:boolean;ready:Record<string,boolean>;nodes?:Array<{node:string;roles:Array<{role:string;available:boolean;status?:{mode:string;ready:Record<string,boolean>}}>}>};
const runtime=ref<RuntimeStatus>(),runtimeUnavailable=ref(false);
const modeNames:Record<string,string>={serving:'运行中',maintenance:'维护中',draining:'正在排空',stopped:'已停止',legacy:'兼容模式'};
const roleNames:Record<string,string>={nginx:'网关入口',management:'管理服务','background-jobs':'后台任务','log-query':'历史日志查询'};
const capabilityNames:Record<string,string>={data:'数据入口',management:'管理服务',acme:'证书签发',status:'证书状态',query:'历史查询','global-jobs':'后台任务','local-cleanup':'本地收尾'};
const sites=ref<Site[]>([]),selected=ref<string[]>([]),from=ref(new Date(Date.now()-3600000).toISOString().slice(0,16)),to=ref(new Date().toISOString().slice(0,16)),result=ref<any>(),error=ref(''),busy=ref(false);
async function load(){busy.value=true;result.value=undefined;error.value='';try{result.value=await request('/statistics/query',{SiteIDs:selected.value,From:new Date(from.value+'Z').toISOString(),To:new Date(to.value+'Z').toISOString()})}catch(e){error.value=message(e)}finally{busy.value=false}}
onMounted(async()=>{request<typeof runtime.value>('/runtime/status').then(value=>{runtime.value=value}).catch(()=>{runtimeUnavailable.value=true});try{sites.value=await all<Site>('/sites')}catch(e){error.value=message(e)}});
</script>
<template><section><h1>站点统计</h1><section class="panel" v-if="runtime" aria-label="管理服务运行状态"><h2>管理服务运行状态</h2><p role="status">{{modeNames[runtime.mode]||runtime.mode}}</p><p v-for="(ready,capability) in runtime.ready" :key="capability">{{capabilityNames[capability]||capability}}：{{ready?'已就绪':'未就绪'}}</p><section v-for="node in runtime.nodes" :key="node.node"><h3>{{node.node}}</h3><p v-for="role in node.roles" :key="role.role">{{roleNames[role.role]||role.role}}：{{role.available&&role.status?(modeNames[role.status.mode]||role.status.mode):'无法获取状态'}}<span v-if="role.status"> · {{Object.entries(role.status.ready).map(([cap,ready])=>`${capabilityNames[cap]||cap} ${ready?'就绪':'未就绪'}`).join('；')}}</span></p></section><p class="muted">各实例和角色独立显示状态；控制服务不可用时，已生效且有效的网关配置仍可提供服务。</p></section><p v-if="runtimeUnavailable" class="muted">当前实例未提供运行状态。</p><p class="muted">Go / PostgreSQL 分钟聚合；延迟来自真实采集水位，百分位为直方图近似值。单次最多 100 站点、24 小时。</p><p v-if="error" role="alert">{{error}}</p><section class="panel"><label v-for="s in sites" :key="s.id" class="check"><input type="checkbox" v-model="selected" :value="s.id">{{s.name}}</label><label>统计开始（UTC）<input aria-label="统计开始（UTC）" type="datetime-local" v-model="from"></label><label>统计结束（UTC）<input type="datetime-local" v-model="to"></label><button @click="load" :disabled="busy||!selected.length">查询统计</button></section><section class="panel" v-if="result" data-testid="statistics"><h2>统计结果</h2><p>请求 {{result.Count}} · 字节 {{result.Bytes}} · P50 {{result.P50Micros}} μs · P95 {{result.P95Micros}} μs（近似）</p><p>采集水位 {{result.IngestedAt.startsWith('0001')?'尚无采集':result.IngestedAt}}</p><p role="status">{{result.IngestedAt.startsWith('0001')?'采集延迟未知，不能认定完整':`采集延迟 ${Math.max(0,Math.floor((Date.now()-Date.parse(result.IngestedAt))/1000))} 秒；水位不代表所有请求均已采集`}}</p></section></section></template>
